// Package postgres runs the managed PostgreSQL: one container per server, a database and a role per app. The agent
// creates the instance (a named volume, a dedicated Docker network, a memory cap, a health check), the databases and
// their roles, stores each URL in the app's variables and declares the database in the apps file, where the backup,
// restore and listing code of the databases package takes over unchanged.
//
// Every secret here is generated by the agent and kept in a file of mode 0600 under <data-dir>/postgres: the
// superuser's password and one password per role. A role's password reaches PostgreSQL as a SCRAM verifier, never as
// the password itself; the superuser's password reaches the instance as a file in the container's own layer and the
// short-lived admin containers as PGPASSWORD, as the database code already does.
package postgres

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"path/filepath"
	"regexp"
	"strings"
	"sync"
	"time"

	"github.com/0x2u/keelson/agent/internal/appenv"
	"github.com/0x2u/keelson/agent/internal/config"
	"github.com/0x2u/keelson/agent/internal/confmgr"
	"github.com/0x2u/keelson/agent/internal/docker"
)

const (
	// instanceLabel is on the instance's container and on its volume and network: it is how the agent knows them
	// for its own, and what keeps another container of the same name from being taken for the instance.
	instanceLabel = "keelson.postgres"
	// specLabel records the settings the container was created with, to tell when the file asks for others.
	specLabel = "keelson.postgres.spec"
	// adminLabel and jobLabel mark the throwaway containers that run SQL: jobLabel makes the leftovers of a crashed
	// agent be removed at the next start, like those of the other throwaway containers.
	adminLabel = "keelson.postgres.admin"
	jobLabel   = "keelson.job"

	stateDirName = "postgres"

	// The instance reads its superuser password from a file written into the container's layer, owned by the
	// postgres user of the alpine image.
	superSecretDir  = "/run/keelson"
	superSecretName = "superuser-password"
	postgresUID     = 70

	dataMount = "/var/lib/postgresql/data"

	opTimeout      = 15 * time.Minute
	healthyTimeout = 3 * time.Minute
	psqlTimeout    = time.Minute
	probeTTL       = time.Minute

	// DefaultKeep is how many backups a managed database keeps unless the request says otherwise.
	DefaultKeep = 7
	// DefaultSchedule is when a managed database is backed up unless the request says otherwise.
	DefaultSchedule = "0 3 * * *"
	// DefaultEnvKey is the variable the URL is stored under unless the request says otherwise.
	DefaultEnvKey = "DATABASE_URL"
)

// Errors the API maps to answers.
var (
	ErrBusy            = errors.New("another operation on the managed PostgreSQL is running: try again in a moment")
	ErrUnknownDatabase = errors.New("unknown managed database")
	ErrUnknownApp      = errors.New("unknown app")
	ErrShuttingDown    = errors.New("the agent is shutting down")
	// ErrForeign: a container is named like the instance but is not the agent's.
	ErrForeign = errors.New("a container named " + config.ManagedPostgresContainer + " exists and is not the agent's: rename or remove it")
	// ErrPasswordLost: the instance's data exist but the file holding the superuser's password does not.
	ErrPasswordLost = errors.New("the instance's data exist but its superuser password file is missing: restore the file from a copy of the data directory, or remove the container and its volume to start again")
)

// RequestError is a request that cannot be accepted; nothing was changed.
type RequestError struct{ Msg string }

func (e *RequestError) Error() string { return e.Msg }

// ConflictError is a request that clashes with what exists; nothing was changed.
type ConflictError struct{ Msg string }

func (e *ConflictError) Error() string { return e.Msg }

// InstanceError is a failure to bring the instance up. Its text is safe to show: it comes from the engine or from the
// agent's own checks, and names no secret.
type InstanceError struct{ Msg string }

func (e *InstanceError) Error() string { return e.Msg }

// ServerError is a failure of a command run against the server. The text is kept for the agent's log: it is what
// PostgreSQL printed.
type ServerError struct{ Err error }

func (e *ServerError) Error() string {
	return "the PostgreSQL server refused a command: " + e.Err.Error()
}
func (e *ServerError) Unwrap() error { return e.Err }

// Engine is the part of the Docker engine the manager needs.
type Engine interface {
	docker.Runner
	Inspect(ctx context.Context, id string) (*docker.Detail, error)
	Remove(ctx context.Context, id string) error
	ListImages(ctx context.Context, repo string) ([]docker.Image, error)
	Pull(ctx context.Context, repo, ref, auth string, progress func(string)) error
	EnsureNetwork(ctx context.Context, name string, labels map[string]string) (bool, error)
	EnsureVolume(ctx context.Context, name string, labels map[string]string) (bool, error)
	VolumeExists(ctx context.Context, name string) (bool, error)
	PutFile(ctx context.Context, container, dir, name string, data []byte, uid, gid int, mode int64) error
}

// Config is the apps file as the manager reads and edits it.
type Config interface {
	Config() *config.Config
	Edit(baseHash string, force bool, meta confmgr.Meta, edit func(disk []byte) ([]byte, []config.Issue, error)) (confmgr.Outcome, error)
}

// Env stores the variables of apps.
type Env interface {
	Apply(app string, ch appenv.Change) (appenv.Result, error)
}

// Options builds a Manager.
type Options struct {
	Engine Engine
	Config Config
	Env    Env
	// Busy reports whether a backup or a restore of the database runs now; nil means never.
	Busy    func(database string) bool
	DataDir string
	Log     *slog.Logger
}

// Manager owns the instance and its databases. It is safe for concurrent use: one operation runs at a time, and a
// request that arrives meanwhile is refused with ErrBusy.
type Manager struct {
	eng  Engine
	cfg  Config
	env  Env
	busy func(string) bool
	dir  string
	log  *slog.Logger
	now  func() time.Time

	// pollEvery is how often the instance's health is checked while waiting for it.
	pollEvery time.Duration
	// healthy bounds that wait.
	healthy time.Duration

	// ctx ends when the agent shuts down: every operation runs under it, so none outlives the process.
	ctx    context.Context
	cancel context.CancelFunc
	wg     sync.WaitGroup

	op sync.Mutex // held by the operation that runs; taken with TryLock

	mu     sync.Mutex
	closed bool
	probe  *probed
	// ensureWarned limits the log to one line per failure: the reconciler retries every half minute.
	ensureWarned string
}

// probed is what the server said about itself, remembered for a minute.
type probed struct {
	at      time.Time
	version string
	size    int64
}

// New returns a Manager. It touches nothing: Reconcile and the requests do.
func New(o Options) *Manager {
	if o.Log == nil {
		o.Log = slog.Default()
	}
	// Paths are handed to Docker and written into the apps file: they must be absolute.
	dir, err := filepath.Abs(o.DataDir)
	if err != nil {
		dir = o.DataDir
	}
	ctx, cancel := context.WithCancel(context.Background())
	busy := o.Busy
	if busy == nil {
		busy = func(string) bool { return false }
	}
	return &Manager{
		eng: o.Engine, cfg: o.Config, env: o.Env, busy: busy, dir: dir, log: o.Log, now: time.Now,
		pollEvery: time.Second, healthy: healthyTimeout, ctx: ctx, cancel: cancel,
	}
}

// Shutdown cancels the operation that runs and waits for it, up to the timeout. Nothing new is accepted. An operation
// cut short is repeated by the client: every step is idempotent.
func (m *Manager) Shutdown(timeout time.Duration) bool {
	m.mu.Lock()
	m.closed = true
	m.mu.Unlock()
	m.cancel()
	done := make(chan struct{})
	go func() { m.wg.Wait(); close(done) }()
	select {
	case <-done:
		return true
	case <-time.After(timeout):
		return false
	}
}

// begin takes the right to run an operation, or says why not. The returned function ends it.
func (m *Manager) begin() (func(), error) {
	m.mu.Lock()
	if m.closed {
		m.mu.Unlock()
		return nil, ErrShuttingDown
	}
	if !m.op.TryLock() {
		m.mu.Unlock()
		return nil, ErrBusy
	}
	m.wg.Add(1)
	m.mu.Unlock()
	return func() { m.op.Unlock(); m.wg.Done() }, nil
}

// opContext is what an operation runs under: the agent's context, not the request's. A client that goes away must not
// leave a role created and a database not, or a container created and never started.
func (m *Manager) opContext() (context.Context, context.CancelFunc) {
	return context.WithTimeout(m.ctx, opTimeout)
}

// Run brings the instance up at once and then keeps it up, every interval, until ctx ends. It only acts while the
// apps file declares a managed database: a server that never asked for one never gets an instance.
func (m *Manager) Run(ctx context.Context, every time.Duration) {
	m.Reconcile(ctx)
	t := time.NewTicker(every)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			m.Reconcile(ctx)
		}
	}
}

// Reconcile makes the instance exist and run when managed databases are declared. It gives way to any operation in
// progress (which ensures the instance itself).
func (m *Manager) Reconcile(ctx context.Context) {
	if len(m.cfg.Config().ManagedDatabases()) == 0 {
		return
	}
	end, err := m.begin()
	if err != nil {
		return
	}
	defer end()
	runCtx, cancel := context.WithTimeout(ctx, opTimeout)
	defer cancel()
	defer context.AfterFunc(m.ctx, cancel)()
	if _, err := m.ensureInstance(runCtx); err != nil {
		if ctx.Err() != nil || m.ctx.Err() != nil {
			return
		}
		msg := m.scrub(err.Error())
		m.mu.Lock()
		again := m.ensureWarned == msg
		m.ensureWarned = msg
		m.mu.Unlock()
		if !again {
			m.log.Warn("the managed PostgreSQL could not be brought up; trying again every few seconds", "err", msg)
		}
		return
	}
	m.mu.Lock()
	m.ensureWarned = ""
	m.mu.Unlock()
}

// --- text that may carry a secret ---------------------------------------------------------------------------

var verifierPattern = regexp.MustCompile(`SCRAM-SHA-256\$\S+`)

// scrub makes text fit for a log or an answer: any secret the caller names is replaced, a SCRAM verifier is
// replaced, lines are joined and the length is bounded.
func (m *Manager) scrub(s string, secrets ...string) string {
	for _, secret := range secrets {
		if secret != "" {
			s = strings.ReplaceAll(s, secret, "***")
		}
	}
	s = verifierPattern.ReplaceAllString(s, "***")
	s = strings.Join(strings.Fields(s), " ")
	if len(s) > 300 {
		s = s[:300] + "..."
	}
	return s
}

func (m *Manager) wrapInstance(format string, args ...any) error {
	return &InstanceError{Msg: m.scrub(fmt.Sprintf(format, args...))}
}
